begin;
with j as (select * from jsonb_to_recordset($law7d0032$[{"code_id":"BK_RF","article_number":"6","version_date":"1998-07-31","article_text":"В целях настоящего Кодекса применяются следующие понятия и термины:\n\nбюджет - форма образования и расходования денежных средств,  предназначенных для финансового обеспечения задач и функций государства и местного самоуправления;\n\nконсолидированный бюджет - свод бюджетов бюджетной системы Российской Федерации на соответствующей территории (за исключением бюджетов государственных внебюджетных фондов)  без учета межбюджетных трансфертов между этими бюджетами;\n\nбюджетная система Российской Федерации - основанная на экономических отношениях и государственном устройстве Российской Федерации,  регулируемая законодательством Российской Федерации совокупность федерального бюджета,  бюджетов субъектов Российской Федерации,  местных бюджетов и бюджетов государственных внебюджетных фондов;\n\nдоходы бюджета - поступающие в бюджет денежные средства,  за исключением средств,  являющихся в соответствии с настоящим Кодексом источниками финансирования дефицита бюджета;\n\nрасходы бюджета - выплачиваемые из бюджета денежные средства,  за исключением средств,  являющихся в соответствии с настоящим Кодексом источниками финансирования дефицита бюджета;\n\nдефицит бюджета - превышение расходов бюджета над его доходами;\n\nпрофицит бюджета - превышение доходов бюджета над его расходами;\n\nбюджетный процесс - регламентируемая законодательством Российской Федерации деятельность органов государственной власти,  органов местного самоуправления и иных участников бюджетного процесса по составлению и рассмотрению проектов бюджетов,  утверждению и исполнению бюджетов,  контролю за их исполнением,  осуществлению бюджетного учета,  составлению,  внешней проверке,  рассмотрению и утверждению бюджетной отчетности;\n\nсводная бюджетная роспись - документ,  который составляется и ведется финансовым органом (органом управления государственным внебюджетным фондом)  в соответствии с настоящим Кодексом в целях организации исполнения бюджета по расходам бюджета и источникам финансирования дефицита бюджета;\n\nбюджетная роспись - документ,  который составляется и ведется главным распорядителем бюджетных средств (главным администратором источников финансирования дефицита бюджета)  в соответствии с настоящим Кодексом в целях исполнения бюджета по расходам (источникам финансирования дефицита бюджета) ;\n\nбюджетные ассигнования - предельные объемы денежных средств,  предусмотренных в соответствующем финансовом году для исполнения бюджетных обязательств;\n\nбюджетный кредит - денежные средства,  предоставляемые бюджетом другому бюджету бюджетной системы Российской Федерации,  юридическому лицу (за исключением государственных (муниципальных)  учреждений) ,  иностранному государству,  иностранному юридическому лицу на возвратной и возмездной основах;\n\nцелевой иностранный кредит  - форма финансирования проектов,  включенных в программу государственных внешних заимствований Российской Федерации,  которая предусматривает предоставление средств в иностранной валюте на возвратной и возмездной основах путем оплаты товаров,  работ и услуг в соответствии с целями этих проектов. Целевые иностранные кредиты включают связанные кредиты иностранных государств,  иностранных юридических лиц,  а также нефинансовые кредиты международных финансовых организаций; (В редакции Федерального закона от 02.08.2019 № 278-ФЗ)\n\nсвязанные кредиты иностранных государств,  иностранных юридических лиц - форма привлечения средств на возвратной и возмездной основах для закупок товаров,  работ и услуг за счет средств иностранных государств,  иностранных юридических лиц в основном в стране кредитора;\n\nнефинансовые кредиты международных финансовых организаций - форма привлечения средств на возвратной и возмездной основах для закупок преимущественно на конкурсной основе товаров,  работ и услуг в целях осуществления инвестиционных проектов или проектов структурных реформ при участии и за счет средств международных финансовых организаций;\n\nгосударственный (муниципальный)  долг - обязательства,  возникающие из государственных (муниципальных)  заимствований,  гарантий по обязательствам третьих лиц,  другие обязательства в соответствии с видами долговых обязательств,  установленными настоящим Кодексом,  принятые на себя Российской Федерацией,  субъектом Российской Федерации или муниципальным образованием; (В редакции Федерального закона от 02.08.2019 № 278-ФЗ)\n\nгосударственный (муниципальный)  внутренний долг - долговые обязательства публично-правового образования,  возникающие в валюте Российской Федерации; (В редакции Федерального закона от 02.08.2019 № 278-ФЗ)\n\nгосударственный (муниципальный)  внешний долг - долговые обязательства публично-правового образования,  возникающие в иностранной валюте; (В редакции Федерального закона от 02.08.2019 № 278-ФЗ)\n\nрасходные обязательства - обусловленные законом,  иным нормативным правовым актом,  договором или соглашением обязанности публично-правового образования (Российской Федерации,  субъекта Российской Федерации,  муниципального образования)  или действующего от его имени казенного учреждения предоставить физическому или юридическому лицу,  иному публично-правовому образованию,  субъекту международного права средства из соответствующего бюджета; (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\n\nбюджетные обязательства - расходные обязательства,  подлежащие исполнению в соответствующем финансовом году;\n\nпубличные обязательства - обусловленные законом,  иным нормативным правовым актом расходные обязательства публично-правового образования перед физическим или юридическим лицом,  иным публично-правовым образованием,  подлежащие исполнению в установленном соответствующим законом,  иным нормативным правовым актом размере и (или)  имеющие установленный указанным законом,  актом порядок его определения (расчета,  индексации) ; (В редакции  Федерального закона от 13.07.2024 № 177-ФЗ)\n\nпубличные нормативные обязательства - публичные обязательства перед физическим лицом,  подлежащие исполнению в денежной форме в установленном соответствующим законом,  иным нормативным правовым актом размере и (или)  порядке расчета размера (индексации) ,  за исключением выплат физическому лицу,  предусмотренных статусом государственных (муниципальных)  служащих,  а также лиц,  замещающих государственные должности Российской Федерации,  государственные должности субъектов Российской Федерации,  муниципальные должности,  работников казенных учреждений,  военнослужащих,  проходящих военную службу по призыву (обладающих статусом военнослужащих,  проходящих военную службу по призыву) ,  лиц,  обучающихся в государственных или муниципальных организациях,  осуществляющих образовательную деятельность; (В редакции  федеральных законов от 08.05.2010 № 83-ФЗ,  от 27.11.2017 № 345-ФЗ,  от 13.07.2024 № 177-ФЗ)\n\nденежные обязательства - обязанность получателя бюджетных средств уплатить бюджету,  физическому лицу и юридическому лицу за счет средств бюджета определенные денежные средства в соответствии с выполненными условиями гражданско-правовой сделки,  заключенной в рамках его бюджетных полномочий,  или в соответствии с положениями закона,  иного правового акта,  условиями договора или соглашения;\n\nмежбюджетные отношения - взаимоотношения между публично-правовыми образованиями по вопросам регулирования бюджетных правоотношений,  организации и осуществления бюджетного процесса;\n\nмежбюджетные трансферты - средства,  предоставляемые одним бюджетом бюджетной системы Российской Федерации другому бюджету бюджетной системы Российско\n\nРОССИЙСКАЯ ФЕДЕРАЦИЯ\n\nБюджетный кодекс Российской Федерации\n\nПринят Государственной Думой                               17 июля 1998 года\n\nОдобрен Советом Федерации                                    17 июля 1998 года\n\n(С учетом федеральных законов от 09.07.1999 № 159-ФЗ,  от 31.12.1999 № 227-ФЗ,  от 27.12.2000 № 150-ФЗ,  от 30.12.2001 № 194-ФЗ,  от 24.12.2002 № 176-ФЗ,  от 23.12.2004 № 173-ФЗ,  от 26.12.2005 № 189-ФЗ,  от 19.12.2006 № 238-ФЗ,  от 01.12.2008 № 225-ФЗ,  от 09.02.2009 № 17-ФЗ,  от 18.07.2009 № 181-ФЗ,  от 28.12.2010 № 402-ФЗ,  от 28.07.2012 № 145-ФЗ,  от 03.02.2014 № 1-ФЗ,  от 29.12.2014 № 473-ФЗ,  от 08.03.2015 № 25-ФЗ,  от 30.03.2016 № 71-ФЗ,  от 02.06.2016 № 158-ФЗ,  от 12.11.2019 № 367-ФЗ,  от 14.07.2022 № 264-ФЗ,  от 05.12.2022 № 466-ФЗ,  от 27.11.2023 № 540-ФЗ,  от 30.09.2024 № 336-ФЗ,  от 29.10.2024 № 367-ФЗ; постановлений Конституционного Суда Российской Федерации от 17.06.2004 № 12-П,  от 22.06.2009 № 10-П,  от 15.07.2021 № 37-П,  от 22.06.2023 № 34-П,  от 25.01.2024 № 3-П)\n\nБюджетный кодекс Российской Федерации устанавливает общие принципы бюджетного законодательства Российской Федерации,  организации и функционирования бюджетной системы Российской Федерации,  правовое положение субъектов бюджетных правоотношений,  определяет основы бюджетного процесса и межбюджетных отношений в Российской Федерации,  порядок исполнения судебных актов по обращению взыскания на средства бюджетов бюджетной системы Российской Федерации,  на подлежащие казначейскому сопровождению в соответствии с настоящим Кодексом средства участников казначейского сопровождения,  порядок применения бюджетных мер принуждения. (В редакции федеральных законов от 20.08.2004 № 120-ФЗ,  от 27.12.2005 № 197-ФЗ,  от 26.07.2019 № 199-ФЗ,  от 01.07.2021 № 244-ФЗ)\n\nЧАСТЬ ПЕРВАЯ. ОБЩИЕ ПОЛОЖЕНИЯ","article_title":"Статья 6. Понятия и термины,  применяемые в настоящем Кодексе","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ad9555964ac361682a8b96188f4169a6de7cf300787025ca3c3dcb6fbf36a153"},{"code_id":"BK_RF","article_number":"60","version_date":"1998-07-31","article_text":"(Статья утратила силу - Федеральный закон от 20.08.2004 № 120-ФЗ)","article_title":"Статья 60.","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d2fc6260056a24b700db74078d4fa449c90263cb9d2bbf7017daa88f1cfa4787"},{"code_id":"BK_RF","article_number":"61","version_date":"1998-07-31","article_text":"(Наименование в редакции Федерального закона от 29.11.2014 № 383-ФЗ)\n\n1. В бюджеты городских поселений зачисляются налоговые доходы от следующих местных налогов,  устанавливаемых представительными органами городских поселений в соответствии с законодательством Российской Федерации о налогах и сборах: (В редакции Федерального закона от 29.11.2014 № 383-ФЗ)\n\nземельного налога - по нормативу 100 процентов;\n\nналога на имущество физических лиц - по нормативу 100 процентов;\n\nтуристического налога - по нормативу 100 процентов. (Дополнение абзацем - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\n2. В бюджеты городских поселений зачисляются налоговые доходы от следующих федеральных налогов и сборов,  в том числе налогов,  предусмотренных специальными налоговыми режимами:\n\nналога на доходы физических лиц (за исключением налога на доходы физических лиц в отношении доходов,  указанных в абзацах тридцать пятом,  тридцать шестом,  тридцать девятом и пятьдесят седьмом статьи 50 настоящего Кодекса и абзацах пятом - одиннадцатом настоящего пункта)  - по нормативу 10 процентов;\n\nединого сельскохозяйственного налога - по нормативу 50 процентов;\n\nгосударственной пошлины за совершение нотариальных действий должностными лицами органов местного самоуправления городского поселения,  уполномоченными в соответствии с законодательными актами Российской Федерации на совершение нотариальных действий,  - по нормативу 100 процентов; (В редакции  Федерального закона от 08.08.2024 № 277-ФЗ)\n\nналога на доходы физических лиц в части суммы налога,  превышающей 312 тысяч рублей,  относящейся к части налоговой базы,  превышающей 2, 4 миллиона рублей и составляющей не более 5 миллионов рублей (за исключением налога на доходы физических лиц в отношении доходов,  указанных в абзаце девятом настоящего пункта) ,  - по нормативу 9 процентов;\n\nналога на доходы физических лиц в части суммы налога,  превышающей 702 тысячи рублей,  относящейся к части налоговой базы,  превышающей 5 миллионов рублей и составляющей не более 20 миллионов рублей (за исключением налога на доходы физических лиц в отношении доходов,  указанных в абзаце девятом настоящего пункта) ,  - по нормативу 8 процентов;\n\nналога на доходы физических лиц в части суммы налога,  превышающей 3402 тысячи рублей,  относящейся к части налоговой базы,  превышающей 20 миллионов рублей и составляющей не более 50 миллионов рублей (за исключением налога на доходы физических лиц в отношении доходов,  указанных в абзаце девятом настоящего пункта) ,  - по нормативу 7 процентов;\n\nналога на доходы физических лиц в части суммы налога,  превышающей 9402 тысячи рублей,  относящейся к части налоговой базы,  превышающей 50 миллионов рублей (за исключением налога на доходы физических лиц в отношении доходов,  указанных в абзаце девятом настоящего пункта) ,  - по нормативу 6 процентов;\n\nналога на доходы физических лиц в части суммы налога,  превышающей 312 тысяч рублей,  относящейся к сумме налоговых баз,  указанных в пункте 6 статьи 210 Налогового кодекса Российской Федерации,  превышающей 2, 4 миллиона рублей (за исключением налога на доходы физических лиц в отношении доходов,  указанных в абзацах тридцать пятом и тридцать шестом статьи 50 настоящего Кодекса) ,  а также налога на доходы физических лиц в отношении доходов физических лиц,  не являющихся налоговыми резидентами Российской Федерации,  указанных в абзаце девятом пункта 3 статьи 224 Налогового кодекса Российской Федерации,  в части суммы налога,  превышающей 312 тысяч рублей,  относящейся к части налоговой базы,  превышающей 2, 4 миллиона рублей,  - по нормативу 9 процентов;\n\nналога на доходы физических лиц в части суммы налога,  относящейся к сумме налоговых баз,  указанных в пункте 61 статьи 210 Налогового кодекса Российской Федерации,  а также налога на доходы физических лиц в части суммы налога,  относящейся к налоговой базе,  указанной в пункте 62 статьи 210 Налогового кодекса Российской Федерации (за исключением налога на доходы физических лиц в отношении доходов,  указанных в абзаце одиннадцатом настоящего пункта) ,  - по нормативу 10 процентов;\n\nналога на доходы физических лиц в части суммы налога,  превышающей 650 тысяч рублей,  относящейся к сумме налоговых баз,  указанных в пункте 61 статьи 210 Налогового кодекса Российской Федерации,  превышающей 5 миллионов рублей,  а также налога на доходы физических лиц в части суммы налога,  превышающей 650 тысяч рублей,  относящейся к налоговой базе,  указанной в пункте 62 статьи 210 Налогового кодекса Российской Федерации,  превышающей 5 миллионов рублей,  - по нормативу 9 процентов.\n\n(Пункт в редакции  Федерального закона от 13.07.2024 № 177-ФЗ)\n\n3. В бюджеты городских поселений зачисляются налоговые доходы от федеральных налогов и сборов,  в том числе налогов,  предусмотренных специальными налоговыми режимами,  и (или)  региональных налогов по нормативам отчислений,  установленным органами государственной власти субъектов Российской Федерации в соответствии со статьей 58 настоящего Кодекса. (В редакции федеральных законов от 26.04.2007 № 63-ФЗ; от 29.11.2014 № 383-ФЗ)\n\n4. В бюджеты городских поселений зачисляются налоговые доходы от федеральных налогов и сборов,  в том числе налогов,  предусмотренных специальными налоговыми режимами,  региональных и (или)  местных налогов по нормативам отчислений,  установленным представительными органами муниципальных районов в соответствии со статьей 63 настоящего Кодекса. (В редакции федеральных законов от 26.04.2007 № 63-ФЗ; от 29.11.2014 № 383-ФЗ)\n\n(Статья в редакции Федерального закона от 20.08.2004 № 120-ФЗ)","article_title":"Статья 61. Налоговые доходы бюджетов городских поселений","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ab05b79df5945718b597cf39c7dd6227292638564c124cb55006afb91a7baec5"}]$law7d0032$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
